const isObject = value => typeof value === 'object' && value !== null && !Array.isArray(value);
const hasShape = (value, required, optional = []) => isObject(value) &&
  required.every(key => Object.hasOwn(value, key)) &&
  Object.keys(value).every(key => required.includes(key) || optional.includes(key));
function matches(value, schema) {
  if (schema.type === 'string') {
    return typeof value === 'string' &&
      (!schema.enum || schema.enum.includes(value)) &&
      (!schema.pattern || new RegExp(schema.pattern).test(value)) &&
      (schema.maxLength === undefined || value.length <= schema.maxLength);
  }
  if (schema.type === 'array') {
    return Array.isArray(value) && value.length >= schema.minItems &&
      value.length <= schema.maxItems && value.every(item => matches(item, schema.items));
  }
  if (schema.type === 'object') {
    return hasShape(value, schema.required) &&
      schema.required.every(key => matches(value[key], schema.properties[key]));
  }
  return false;
}
